@AbapCatalog.sqlViewName: 'ZCDS_AVG_FLIGHTS'
@AbapCatalog.compiler.compareFilter: true
@AbapCatalog.preserveKey: true
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'Average Flight Price 2024'
define view ZCDS_AverageFlightPrice2024
  as select from sflights
{
  key carrid,
  key connid,
      avg( price ) as AveragePrice
}
where
      fldate between '20240101' and '20241231'
group by
  carrid,
  connid;
